import { readFile } from "node:fs/promises";
import path from "node:path";
import { UPLOAD_DIR } from "@/lib/fighter-store";

// Sprite names are generated by the server; anything else is rejected.
const SPRITE_NAME = /^[a-f0-9]{16}\.png$/;

export async function GET(
  _request: Request,
  { params }: RouteContext<"/uploads/[file]">,
) {
  const { file } = await params;
  if (!SPRITE_NAME.test(file)) return new Response(null, { status: 404 });

  try {
    const sprite = await readFile(path.join(UPLOAD_DIR, file));
    return new Response(new Uint8Array(sprite), {
      headers: {
        "Content-Type": "image/png",
        "Cache-Control": "public, max-age=31536000, immutable",
      },
    });
  } catch {
    return new Response(null, { status: 404 });
  }
}
